def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    slots = int(supply // WATER_REQ)
    if slots < 0:
        slots = 0

    prev_bids = []
    aggressive = 0
    weak_opp_count = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if bid >= 120:
                aggressive += 1
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2 or opp.get('budget', 0) < 40:
            weak_opp_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    alive_count = len(alive_opponents)

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1
    if no_water >= 2:
        danger += 3
    elif no_water >= 1:
        danger += 1

    if alive_count == 0:
        if danger >= 3:
            return float(min(budget, 20.0))
        return float(min(budget, 5.0))

    if slots >= 2:
        if danger >= 5:
            bid = 95.0
        elif danger >= 3:
            bid = 58.0
        else:
            if aggressive >= 2:
                bid = 9.0
            elif highest_prev >= 150:
                bid = 12.0
            else:
                bid = 18.0
    else:
        if danger >= 5:
            bid = max(110.0, highest_prev + 3.0)
        elif danger >= 3:
            bid = max(82.0, min(118.0, avg_prev + 6.0))
        else:
            if aggressive >= 2:
                bid = 22.0
            elif highest_prev >= 150:
                bid = 28.0
            else:
                bid = max(35.0, min(75.0, highest_prev + 2.0))

    if weak_opp_count >= 2 and danger <= 2:
        bid *= 0.8

    if budget < DAILY_SALARY:
        bid = min(bid, budget * 0.75)
    else:
        bid = min(bid, budget * 0.6)

    if danger >= 5:
        bid = max(bid, min(budget, 90.0))
    elif danger >= 3:
        bid = max(bid, min(budget, 55.0))

    if bid < 0:
        bid = 0.0
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
    if yesterday_bids:
        avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids)
        bid = avg_prev_bid * 1.05
        if my_status['hp'] <= 3:
            bid = max(bid, DAILY_SALARY * 0.8)
    else:
        bid = DAILY_SALARY * 0.6
    return min(my_status['budget'], float(bid))
